const CACHE='veihotell-shell-v46';const ASSETS=['./','./index.html','./nearby.html','./style.css?v=46','./app.js?v=46','./hotel-chains.js?v=46','./place-suggestions.js?v=46','./kartverket-places.js?v=46','./settlement-point.js?v=46','./geo.js?v=46','./nearby.js?v=46','./poi.js?v=46','./map-view.js?v=46','./places.json','./hotels.json','./manifest.webmanifest','./icon.svg','./icon-192.png','./icon-512.png'];
self.addEventListener('install',event=>{event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(ASSETS)).then(()=>self.skipWaiting()));});
self.addEventListener('activate',event=>{event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('veihotell-shell-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim()));});
self.addEventListener('fetch',event=>{if(event.request.method!=='GET')return;const url=new URL(event.request.url);if(url.origin===self.location.origin){if(event.request.mode==='navigate'){event.respondWith(fetch(event.request).catch(()=>caches.match(url.pathname.endsWith('/nearby.html')?'./nearby.html':'./index.html')));return;}if(ASSETS.some(asset=>new URL(asset,self.registration.scope).pathname===url.pathname))event.respondWith(fetch(event.request).then(response=>{if(response.ok){const copy=response.clone();event.waitUntil(caches.open(CACHE).then(cache=>cache.put(event.request,copy)));}return response;}).catch(()=>caches.match(event.request)));}else if(url.hostname==='unpkg.com'&&/^\/leaflet@1\.9\.4\/dist\/(leaflet\.js|leaflet\.css)$/.test(url.pathname)){event.respondWith(caches.open(CACHE).then(async cache=>{const cached=await cache.match(event.request);if(cached)return cached;const response=await fetch(event.request);if(response.ok)await cache.put(event.request,response.clone());return response;}));}});

